1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "title": "investigation answer",
4	  "type": "object",
5	  "additionalProperties": false,
6	  "required": ["schema_version", "mechanism", "notation", "causal_chain", "timeline", "confidence"],
7	  "$defs": {
8	    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})?$"},
9	    "id": {"type": "string", "pattern": "^[a-z_]+:[A-Za-z0-9_.@/:-]+$"},
10	    "zone": {"type": "string", "pattern": "^[A-Z]$"},
11	    "conf": {"type": "number", "minimum": 0, "maximum": 1},
12	    "PHYSICAL_TYPES": {"enum": ["door_prop", "door_open", "trip", "lockout", "defrost", "excursion", "compressor_fault", "sensor_fault", "power_loss", "frame_burst"]},
13	    "DATA_TYPES": {"enum": ["readings_wrong", "lots_wrong", "alerts_suppressed", "frames_dropped", "quarantine_wrong"]},
14	    "ACTIONS": {"enum": ["door_prop", "door_open", "door_close", "pallet_move", "firmware_flash", "config_edit", "commit", "override_deploy", "archive_channel", "probe_check", "ticket_open", "ticket_close", "alert_ack", "statement", "quarantine", "shift_start", "shift_end", "purchase", "photo", "postmortem_publish"]},
15	    "DEFROST_RULE_TYPES": {"enum": ["runtime_hours", "wall_clock", "temperature"]},
16	    "V34_CHANGE": {"enum": ["absolute_temp", "delta_temp", "unit_change", "scale_change", "none"]},
17	    "AFFIX_ROLES": {"enum": ["ZONE", "ASPECT_EVENT", "ASPECT_STATE", "NEGATION", "PLURAL"]},
18	    "NOTATION_LABELS": {"enum": ["HDR", "ZONE_A", "ZONE_B", "ZONE_C", "ZONE_D", "ZONE_E", "ZONE_F", "ZONE_G", "ZONE_H", "RUN", "IDLE", "DEFROST", "RECOVERY", "LOCKOUT", "TRIP", "AIR_TEMP", "COIL_TEMP", "DISCH_PRESSURE", "DOOR", "HEATER", "SETPOINT", "COMPRESSOR", "FIRMWARE", "QUEUE", "READ", "ENTER", "EXIT", "SET", "FAULT", "CLEAR", "BOOT", "OPEN", "CLOSED", "ON", "OFF", "HIGH", "LOW", "STALE", "ABS", "OVERFLOW", "DIGIT_0", "DIGIT_1", "DIGIT_2", "DIGIT_3", "DIGIT_4", "DIGIT_5", "DIGIT_6", "DIGIT_7", "DIGIT_8", "DIGIT_9", "DIGIT_10", "DIGIT_11"]},
19	    "CHANNELS": {"enum": ["badge", "exif", "cctv", "forklift", "chat", "tickets", "git", "submeter", "gateway", "probe"]}
20	  },
21	  "properties": {
22	    "schema_version": {"const": "1"},
23	    "mechanism": {
24	      "type": "object", "additionalProperties": false,
25	      "properties": {
26	        "parameters": {"type": "object", "additionalProperties": {"type": "number"}},
27	        "rules": {
28	          "type": "object", "additionalProperties": false,
29	          "properties": {
30	            "defrost_rule_type": {"$ref": "#/$defs/DEFROST_RULE_TYPES"},
31	            "stagger_order": {"type": "array", "items": {"$ref": "#/$defs/zone"}},
32	            "adjacency_pairs": {"type": "array", "items": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"$ref": "#/$defs/zone"}}}
33	          }
34	        }
35	      }
36	    },
37	    "notation": {
38	      "type": "object", "additionalProperties": false,
39	      "properties": {
40	        "glossary": {"type": "object", "additionalProperties": {"$ref": "#/$defs/NOTATION_LABELS"}},
41	        "affixes": {"type": "object", "additionalProperties": {"$ref": "#/$defs/AFFIX_ROLES"}},
42	        "v34_change": {"$ref": "#/$defs/V34_CHANGE"},
43	        "heldout": {"type": "array", "items": {
44	          "type": "object", "additionalProperties": false,
45	          "required": ["seq", "event", "zone"],
46	          "properties": {
47	            "seq": {"type": "integer"},
48	            "ts": {"$ref": "#/$defs/iso"},
49	            "zone": {"$ref": "#/$defs/zone"},
50	            "event": {"$ref": "#/$defs/NOTATION_LABELS"},
51	            "value": {"type": ["number", "null"]}
52	          }}}
53	      }
54	    },
55	    "causal_chain": {
56	      "type": "object", "additionalProperties": false,
57	      "properties": {
58	        "roots": {"type": "array", "items": {"$ref": "#/$defs/id"}},
59	        "nodes": {"type": "array", "items": {"$ref": "#/$defs/id"}},
60	        "edges": {"type": "array", "items": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"$ref": "#/$defs/id"}}},
61	        "decoys_rejected": {"type": "array", "items": {"$ref": "#/$defs/id"}},
62	        "affected_lots": {"type": "array", "items": {"$ref": "#/$defs/id"}},
63	        "excursion": {"type": "object", "additionalProperties": false,
64	          "properties": {"zone": {"$ref": "#/$defs/zone"}, "start": {"$ref": "#/$defs/iso"}, "end": {"$ref": "#/$defs/iso"}}}
65	      }
66	    },
67	    "timeline": {
68	      "type": "object", "additionalProperties": false,
69	      "properties": {
70	        "events": {"type": "array", "items": {
71	          "type": "object", "additionalProperties": false,
72	          "required": ["actor", "action", "t"],
73	          "properties": {
74	            "actor": {"$ref": "#/$defs/id"},
75	            "action": {"$ref": "#/$defs/ACTIONS"},
76	            "t": {"$ref": "#/$defs/iso"},
77	            "ref": {"type": "string"}
78	          }}},
79	        "clock_offsets_min": {"type": "object", "propertyNames": {"$ref": "#/$defs/CHANNELS"}, "additionalProperties": {"type": "number"}},
80	        "false_claims": {"type": "array", "items": {
81	          "type": "object", "additionalProperties": false,
82	          "required": ["doc_id", "quote"],
83	          "properties": {"doc_id": {"$ref": "#/$defs/id"}, "quote": {"type": "string", "minLength": 8}}}}
84	      }
85	    },
86	    "confidence": {
87	      "type": "object", "additionalProperties": false,
88	      "properties": {"mechanism": {"$ref": "#/$defs/conf"}, "notation": {"$ref": "#/$defs/conf"},
89	                     "causal_chain": {"$ref": "#/$defs/conf"}, "timeline": {"$ref": "#/$defs/conf"}}
90	    }
91	  }
92	}

